/**
 * The verify portal favicons: the REAL dmj.one logo (assets/logo round.png,
 * the circular watercolor badge with the cursive wordmark), resized offline
 * to favicon sizes and embedded here so the in-memory routes serve it with
 * no filesystem, no extra Docker layer and no CDN (same pattern as the
 * font-bytes module). 32px answers tabs + /favicon.ico probes; 180px serves
 * apple-touch-icon (home-screen) requests.
 *
 * GENERATED bytes - regenerate by resizing assets/logo round.png (1500px)
 * via a high-quality two-step downscale (1500 -> 512 -> target).
 */

const FAVICON_PNG_32_B64 =
  "";

const FAVICON_PNG_180_B64 =
  "";

/** Decoded once at module load; routes slice fresh ArrayBuffers per response. */
export const FAVICON_PNG_32: Buffer = Buffer.from(FAVICON_PNG_32_B64, 'base64');
export const FAVICON_PNG_180: Buffer = Buffer.from(FAVICON_PNG_180_B64, 'base64');
